{"arguments": {"code": "S = load('inputs_P56-SIG-F.mat');
n = double(S.nBits); k = double(S.nErr); ebndB = double(S.spec.ebn0dB); conf = double(S.spec.level);
g = 10^(ebndB/10);                      % Eb/N0 linear
p0 = 0.5*erfc(sqrt(g));                 % Q(sqrt(2*Eb/N0)) for QPSK = 0.5*erfc(sqrt(Eb/N0))
phat = k/n;
try, zc = norminv((1+conf)/2); catch, zc = 1.959963984540054; end
muExp = p0*n;
se0 = sqrt(p0*(1-p0)/n);
zprop = (phat - p0)/se0;
zpois = (k - muExp)/sqrt(muExp);
den = 1 + zc^2/n;
ctr = (phat + zc^2/(2*n))/den;
hw = zc/den*sqrt(phat*(1-p0*0)/n*0 + phat*(1-phat)/n + zc^2/(4*n^2));
lo = ctr - hw; hi = ctr + hw;
inCI = (p0>=lo)&&(p0<=hi);
significant = abs(zprop) > zc;
if inCI && significant, state='INCONCLUSIVE'; elseif inCI, state='SUPPORT'; verdict='PASS'; else, if significant, state='REFUTE'; verdict='FAIL'; else, state='INCONCLUSIVE'; verdict='UNDETERMINED'; end; end
try, pval = 2*normcdf(-abs(zprop)); catch, pval = NaN; end
fprintf('EbN0_lin   = %.12g\n', g);
fprintf('p_theory   = %.12g\n', p0);
fprintf('phat       = %.12g\n', phat);
fprintf('muExp      = %.12g\n', muExp);
fprintf('z_prop     = %.12g\n', zprop);
fprintf('z_poisson  = %.12g\n', zpois);
fprintf('se0        = %.12g\n', se0);
fprintf('zcrit      = %.12g\n', zc);
fprintf('wilson     = [%.12g, %.12g]\n', lo, hi);
fprintf('pval       = %.12g\n', pval);
fprintf('inCI=%d sig=%d state=%s verdict=%s\n', inCI, significant, state, verdict);
clear hw den ctr zc g", "project_path": "E:\desktop\MATLAB-bench-phase56\arms\R1\P56-SIG-F"}, "toolName": "mcp__matlab_official__evaluate_matlab_code"}

