{"arguments": {"code": "S = load('inputs_P56-SIG-F.mat');
nErr = S.nErr; n = S.nBits; ebn0Db = S.spec.ebn0Db; conf = S.spec.level;
assert(strcmp(S.spec.scheme,'QPSK'));
% --- theory: exact BPSK/QPSK BER = 0.5*erfc(sqrt(Eb/N0)) ---
ebn0 = 10^(ebn0Db/10);
p0 = 0.5*erfc(sqrt(ebn0));
theoryExpectedEvents = p0*n;
phat = nErr/n;
% --- z-test against counting noise (contract section 8: |z| <= 3) ---
z = (phat - p0)/sqrt(p0*(1-p0)/n);
zCritAbs = 3;
pTwoSided = erfc(abs(z)/sqrt(2));
% --- Wilson score interval on the OBSERVED proportion, literal zq ---
zq = 1.959963984540054;
den = 1 + zq^2/n;
ctr = (phat + zq^2/(2*n))/den;
half = (zq/den)*sqrt(phat*(1-phat)/n + zq^2/(4*n^2));
ciLo = ctr - half; ciHi = ctr + half;
ciExcludesTheory = (ciLo > p0) || (ciHi < p0);
% --- five-state funnel ---
criterionMissing = ~(isfinite(zCritAbs) && conf > 0 && conf < 1);
if criterionMissing
  state = 'criterion-missing';
elseif theoryExpectedEvents < 10
  state = 'insufficient-sample';
elseif abs(z) <= zCritAbs && ~ciExcludesTheory
  state = 'sufficient-support';
elseif abs(z) > zCritAbs && ciExcludesTheory
