{"arguments": {"code": "in = load('E:/desktop/MATLAB-bench-phase56/arms/R2/P56-SIG-B/inputs_P56-SIG-B.mat');
nErr = in.nErr; nBits = in.nBits; sp = in.spec;
target = sp.targetBer; level = sp.level; ebn0Lin = 10^(sp.ebn0dB/10);
zq = 1.959963984540054;
% Wilson score interval, 95%
pHat = nErr/nBits;
den = 1 + zq^2/nBits;
ciLo = (pHat + zq^2/(2*nBits) - zq*sqrt(pHat*(1-pHat)/nBits + zq^2/(4*nBits^2)))/den;
ciUp = (pHat + zq^2/(2*nBits) + zq*sqrt(pHat*(1-pHat)/nBits + zq^2/(4*nBits^2)))/den;
% exact zero-error (Clopper-Pearson style) upper bound for 0 events
exactUp = 1 - (1-level/100*0 + (1-0.95))^(1/nBits);
% theory QPSK = BPSK: 0.5*erfc(sqrt(Eb/N0))
theoryBer = 0.5*erfc(sqrt(ebn0Lin));
theoryExpectedEvents = nBits*theoryBer;
zTheory = (pHat - theoryBer)/sqrt(theoryBer*(1-theoryBer)/nBits);
pZeroGivenTheory = (1-theoryBer)^nBits;
expectedAtTarget = nBits*target;
nNeededFor100 = ceil(100/target);
% decision
if ciUp <= target
  state = 'sufficient-support'; verdict = 'PASS';
elseif ciLo >= target
  state = 'sufficient-refutation'; verdict = 'FAIL';
elseif expectedAtTarget < 10
  state = 'insufficient-sample'; verdict = 'UNDETERMINED';
else
  state = 'interval-straddles-target'; verdict = 'UNDETERMINED';
end
fprintf('pHat            %.6g\n', pHat);
fprintf('ebn0Lin         %.10g\n', ebn0Lin);
fprintf('theoryBer       %.10g\n', theoryBer);
fprintf('theoryExpected  %.10g\n', theoryExpectedEvents);
fprintf('expectedAtTarget %.10g\n', expectedAtTarget);
fprintf('wilsonLo        %.10g\n', ciLo);
fprintf('wilsonUp        %.10g\n', ciUp);
fprintf('exactZeroUp95   %.10g\n', exactUp);
fprintf('zVsTheory       %.6g\n', zTheory);
fprintf('P(0err|theory)  %.6g\n', pZeroGivenTheory);
fprintf('bitsNeeded~100e %d\n', nNeededFor100);
fprintf('STATE=%s VERDICT=%s\n', state, verdict);
out = sprintf('{\n  "verdict": "%s",\n  "fields": {\n    "verdict": "%s",\n    "state": "%s",\n    "ciWilsonUpper95": %.6g,\n    "theoryExpectedEvents": %.6g,\n    "nBits": %d\n  }\n}\n', verdict, verdict, state, ciUp, theoryExpectedEvents, nBits);
fid = fopen('E:/desktop/MATLAB-bench-phase56/arms/R2/P56-SIG-B/result.json','w');
fwrite(fid, out); fclose(fid);
fprintf('--- result.json ---\n%s', out);"}, "toolName": "mcp__matlab_official__evaluate_matlab_code"}

