{"arguments": {"code": "root = 'E:/desktop/MATLAB-bench-phase56/arms/R3/P56-SIG-F';
nErr = 550; n = 1e6; ebn0dB = 8.8; L = 0.95;
% --- route B: Q-function form of the QPSK BER (independent of 0.5*erfc) ---
g = 10^(ebn0dB/10);
pQ = 0.5*erfc(sqrt(g));
pQ2 = qfunc(sqrt(2*g));
fprintf('theory 0.5*erfc(sqrt(g)) = %.12g\n', pQ);
fprintf('theory qfunc(sqrt(2g))   = %.12g\n', pQ2);
fprintf('abs diff                 = %.3g\n', abs(pQ-pQ2));
% --- route B: z from the event counts, not the rates ---
p0 = pQ; mu = p0*n; sig = sqrt(n*p0*(1-p0));
zB = (nErr - mu)/sig;
zA = (nErr/n - p0)/sqrt(p0*(1-p0)/n);
fprintf('z via rates = %.12g   z via counts = %.12g   diff = %.3g\n', zA, zB, abs(zA-zB));
fprintf('theoryExpectedEvents = %.12g\n', mu);
% --- route B: Wilson with the literal two-sided quantile ---
zq = abs(norminv(1-(1-L)/2));
den = 1 + zq^2/n; phat = nErr/n;
cen = (phat + zq^2/(2*n))/den;
half = zq/den*sqrt(phat*(1-phat)/n + zq^2/(4*n^2));
lo = cen-half; hi = cen+half;
fprintf('zq = %.15f\nWilson lo = %.15g\nWilson hi = %.15g\n', zq, lo, hi);
% --- Clopper-Pearson exact interval as a sanity comparison ---
cpLo = betainc((1-L)/2, nErr, n-nErr+1); cpHi = betainc((1+L)/2, nErr+1, n-nErr);
fprintf('CP exact  lo = %.12g  hi = %.12g\n', cpLo, cpHi);
fprintf('theory inside Wilson? %d ; inside CP? %d\n', lo<=p0 & p0<=hi, cpLo<=p0 & p0<=cpHi);
fprintf('phat/p0 = %.6g  ; two-sided p-value = %.6g\n', phat/p0, 2*(1-normcdf(abs(zA))));

% --- write result.json ---
res = struct();
res.verdict = 'FAIL';
f = struct();
f.verdict = 'FAIL';
f.state = 'sufficient-refutation';
f.z = zA;
f.theoryExpectedEvents = mu;
f.ciWilsonLower95 = lo;
f.ciWilsonUpper95 = hi;
res.fields = f;
res.statistic = 'z = (p_hat - p_theory)/sqrt(p_theory(1-p_theory)/n), two-sided Wilson 95%% score interval, |z|<=3 acceptance';
res.measuredBer = phat; res.theoryBer = p0; res.nErr = nErr; res.nBits = n; res.ebn0dB = ebn0dB;
js = jsonencode(res);
fid = fopen(fullfile(root,'result.json'),'w');
fwrite(fid, js);
fclose(fid);
fprintf('WROTE result.json:\n%s\n', js);"}, "toolName": "mcp__matlab_official__evaluate_matlab_code"}

{"arguments": {"code": "root = 'E:/desktop/MATLAB-bench-phase56/arms/R3/P56-SIG-F';
nErr = 550; n = 1e6; L = 0.95; phat = nErr/n;
p0 = 0.5*erfc(sqrt(10^0.88));
% correct Clopper-Pearson (unregularized inverse via betainc 'regularized',false route)
cpLo = betainc((1-L)/2, nErr, n-nErr+1, 'regularized', false);
cpHi = betainc((1+L)/2, nErr+1, n-nErr, 'regularized', false);
if ~(cpLo>0 && cpLo<1), cpLo = betaincinv(nErr, n-nErr+1, (1-L)/2); cpHi = betaincinv(nErr+1, n-nErr, (1+L)/2); end
