fprintf('theory in CP? %d (theory %.6g below CP lo %.6g)\n', cpLo<=p0 & p0<=cpHi, p0, cpLo);
zq = abs(norminv(1-(1-L)/2)); den = 1+zq^2/n; cen = (phat+zq^2/(2*n))/den;
half = zq/den*sqrt(phat*(1-phat)/n + zq^2/(4*n^2)); lo = cen-half; hi = cen+half;
